package br.com.equilibra.goal.infrastructure; import br.com.equilibra.goal.domain.GoalContribution; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.math.BigDecimal; import java.util.*; public interface GoalContributionRepository extends JpaRepository<GoalContribution,String>{@Query("select coalesce(sum(c.amount),0) from GoalContribution c where c.ownerId=:owner and c.goalId=:goal") BigDecimal sumForGoal(String owner,String goal);}
